/**
 * Design-spec application regression on one app: the Clean Cart slice's app (eval 1), regenerated by FlowCode as in
 * functional-journey.test.ts, with two deliberately contrasting controlled specs applied to separate copies. The
 * rendered app must differ in typography, hierarchy, density, surface treatment and palette (colour alone doesn't
 * count), every token requirement must read as implemented, the coder's requirements must stay the coder's, the
 * functional journey must still pass, and a text-only change must not count as implementing a spec. A pipeline
 * regression, not a judgement that either design is good. Needs the recorded workspace and a browser.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, type ChildProcess } from "node:child_process";
import { afterAll, describe, expect, it } from "vitest";
import { chromium, type Browser } from "playwright";
import { journeyPlan, runJourney } from "../src/quality/appJourney.js";
import { measureDesign, specImplementation, specMeasureTokens, type MeasuredDesign } from "../src/quality/designSpecCheck.js";
import { applyDesignSpec, type DesignSpec, type SpecApplication } from "../src/workspace/designSpec.js";
import { prdNamedRecords, prdSampleSection, resolveScreenAliases, type AppModel } from "../src/orchestrator/appModel.js";
import { declaredScreens } from "../src/orchestrator/screenPlan.js";
import { mergeRecords, prdFixtureRows } from "../src/orchestrator/recordIdentity.js";
import { appFiles } from "../src/orchestrator/appFiles.js";
import { syncedLibraryCss } from "../src/orchestrator/sectionRecipes.js";
import { makeApp } from "./helpers.js";

const REPO = path.resolve(import.meta.dirname, "../../..");
const RECORDED = path.join(REPO, ".flowcode-data/workspaces/clean-cart-slice-eval-1-9b1947");
const PRD = fs.readFileSync(path.join(REPO, "docs/handoff/slice/clean-cart-slice-prd.md"), "utf8");
const MODEL = JSON.parse(fs.readFileSync(path.join(import.meta.dirname, "fixtures/apps/eval1-app-model.json"), "utf8")) as AppModel;
const SCREENS = declaredScreens(PRD);
const NAMED = prdNamedRecords(prdSampleSection(PRD));
const fixture = (name: string) => JSON.parse(fs.readFileSync(path.join(import.meta.dirname, "fixtures/design", name), "utf8")) as DesignSpec;
const A = fixture("spec-field-notes.json");
const B = fixture("spec-bold-aisle.json");
/** Where screenshots for the person's review go, when asked for (FLOWCODE_SPEC_SHOTS=<dir>). */
const SHOTS = process.env.FLOWCODE_SPEC_SHOTS;

const prdRows = (e: AppModel["entities"][number]) => prdFixtureRows(e, prdSampleSection(PRD));
const seed = Object.fromEntries(MODEL.entities.map((e) => [e.key, mergeRecords(e, [], MODEL.seed[e.key] ?? [], { prdRows: prdRows(e) }).rows]));
const FIXED = resolveScreenAliases({ ...MODEL, seed }, SCREENS);

/** A copy of the regenerated app (node_modules linked), optionally with files replaced. */
function copyApp(files: Array<{ path: string; content: string }> = []): string {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "fc-spec-"));
  const walk = (from: string, to: string) => {
    for (const e of fs.readdirSync(from, { withFileTypes: true })) {
      if (["node_modules", "dist", ".git"].includes(e.name)) continue;
      const s = path.join(from, e.name);
      const d = path.join(to, e.name);
      if (e.isDirectory()) (fs.mkdirSync(d, { recursive: true }), walk(s, d));
      else fs.copyFileSync(s, d);
    }
  };
  walk(RECORDED, root);
  fs.symlinkSync(path.join(RECORDED, "node_modules"), path.join(root, "node_modules"), "junction");
  for (const f of [...appFiles(FIXED).filter((f) => !f.path.startsWith("src/screens/")), ...files]) (fs.mkdirSync(path.dirname(path.join(root, f.path)), { recursive: true }), fs.writeFileSync(path.join(root, f.path), f.content));
  // The library's styles as FlowCode writes them now (it rebuilds library.css from the templates when it writes the app).
  const css = syncedLibraryCss(root);
  if (css !== undefined) fs.writeFileSync(path.join(root, "src/styles/library.css"), css);
  return root;
}

const servers: ChildProcess[] = [];
let browser: Browser | undefined;
async function serve(root: string, port: number): Promise<string> {
  const p = spawn(process.execPath, [path.join(root, "node_modules/vite/bin/vite.js"), "--port", String(port), "--strictPort", "--host", "127.0.0.1"], { cwd: root, stdio: ["ignore", "pipe", "pipe"] });
  servers.push(p);
  const url = `http://127.0.0.1:${port}/`;
  for (let i = 0; i < 120; i++) {
    if (await fetch(url).then((r) => r.ok, () => false)) return url;
    await new Promise((r) => setTimeout(r, 500));
  }
  throw new Error("vite didn't start");
}

interface Rendered {
  application?: SpecApplication;
  applyMs: number;
  measured: MeasuredDesign;
  verifyMs: number;
  journeyOk: boolean;
  journeyFailed: string[];
  journeyMs: number;
}
/** Applies a spec (unless none) to a fresh copy, serves it, measures the design on Home and runs the journey. */
async function render(spec: DesignSpec | undefined, port: number, measureAs: DesignSpec, files: Array<{ path: string; content: string }> = []): Promise<Rendered> {
  const root = copyApp(files);
  let application: SpecApplication | undefined;
  let applyMs = 0;
  if (spec) {
    const { app } = makeApp();
    const project = app.projects.create({ name: `Spec ${spec.id}`, workspacePath: root });
    const t = performance.now();
    application = applyDesignSpec(app.projects.jail(project), app.ops, { projectId: project.id, runId: "spec_regression" }, spec, { frameCss: "src/styles/components.css", screens: fs.readdirSync(path.join(root, "src/screens")).map((f) => `src/screens/${f}`) });
    applyMs = performance.now() - t;
  }
  const url = await serve(root, port);
  browser ??= await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 860 } });
  await page.goto(url, { waitUntil: "networkidle" });
  await page.evaluate(() => document.fonts.ready);
  const t = performance.now();
  const measured = await measureDesign(page, specMeasureTokens(measureAs));
  const verifyMs = performance.now() - t;
  if (SHOTS) (fs.mkdirSync(SHOTS, { recursive: true }), await page.screenshot({ path: path.join(SHOTS, `${spec?.id ?? "unstyled"}-${port}.png`), fullPage: true }));
  await page.close();
  const jp = await browser.newPage({ viewport: { width: 1280, height: 860 } });
  const tj = performance.now();
  const journey = await runJourney(jp, url, journeyPlan(FIXED, SCREENS, NAMED));
  const journeyMs = performance.now() - tj;
  await jp.close();
  return { application, applyMs, measured, verifyMs, journeyOk: journey.ok, journeyFailed: journey.steps.filter((s) => !s.ok).map((s) => `${s.step}: ${s.detail}`), journeyMs };
}

afterAll(async () => {
  await browser?.close();
  for (const p of servers) p.kill();
});

describe.skipIf(process.env.FLOWCODE_SKIP_BROWSER === "1" || !fs.existsSync(path.join(RECORDED, "node_modules")))("two design specs on the same app", () => {
  it("render differently in typography, hierarchy, density, surface and palette; the journey still passes; coder work stays the coder's", async () => {
    const a = await render(A, 5351, A);
    const b = await render(B, 5352, B);
    const ra = specImplementation(A, a.measured, { requirements: a.application!.requirements });
    const rb = specImplementation(B, b.measured, { requirements: b.application!.requirements });
    const status = (rs: typeof ra) => Object.fromEntries(rs.map((r) => [r.id, r.status]));
    if (SHOTS) fs.writeFileSync(path.join(SHOTS, "evidence.json"), JSON.stringify({ A: ra, B: rb, timings: { A: { applyMs: a.applyMs, verifyMs: a.verifyMs, journeyMs: a.journeyMs }, B: { applyMs: b.applyMs, verifyMs: b.verifyMs, journeyMs: b.journeyMs } }, measured: { A: a.measured, B: b.measured } }, null, 2));

    // Every token requirement is implemented in the rendered app; the coder's are open, never claimed.
    const tokensOnly = (rs: typeof ra) => rs.filter((r) => r.by === "tokens");
    expect(tokensOnly(ra).filter((r) => r.status !== "implemented")).toEqual([]);
    expect(tokensOnly(rb).filter((r) => r.status !== "implemented")).toEqual([]);
    expect(status(ra)).toMatchObject({ "composition-1": "for the coder", signature: "for the coder", "responsive-1": "for the coder" });
    expect(status(rb)).toMatchObject({ "heading-case": "for the coder", "composition-1": "for the coder", signature: "for the coder", "responsive-1": "for the coder" });

    // The two renders differ on every dimension, not only colour.
    const ma = a.measured;
    const mb = b.measured;
    // Typography: the families.
    expect(ma.heading!.fontFamily).not.toBe(mb.heading!.fontFamily);
    expect(ma.body.fontFamily).not.toBe(mb.body.fontFamily);
    // Hierarchy: how far the heading steps up from the text.
    const ratio = (m: MeasuredDesign) => m.heading!.fontSize / m.body.fontSize;
    expect(ratio(ma) / ratio(mb)).toBeGreaterThan(1.4);
    expect(ma.heading!.fontWeight).not.toBe(mb.heading!.fontWeight);
    // Density: a card's padding.
    expect(ma.surface!.padding).toBeGreaterThan(mb.surface!.padding * 1.3);
    // Surface treatment: corners, outline and shadow.
    expect(ma.surface!.radius).not.toBe(mb.surface!.radius);
    expect(ma.surface!.borderWidth).not.toBe(mb.surface!.borderWidth);
    expect(ma.surface!.boxShadow).not.toBe(mb.surface!.boxShadow);
    // Palette.
    expect(ma.body.background).not.toBe(mb.body.background);

    // Function is kept.
    expect(a.journeyFailed).toEqual([]);
    expect(b.journeyFailed).toEqual([]);
  }, 300_000);

  it("a text-only change doesn't implement a spec", async () => {
    // Measured against Bold Aisle, which differs from the starter on every token (Field Notes' flat surfaces are the starter's own).
    // The same app with only words changed (a heading's text), and no spec applied.
    const home = fs.readdirSync(path.join(RECORDED, "src/screens")).find((f) => /home/i.test(f));
    const src = home ? fs.readFileSync(path.join(RECORDED, "src/screens", home), "utf8") : "";
    const files = home ? [{ path: `src/screens/${home}`, content: src.replace(/>([^<>{}]{4,40})</, ">BOLD AISLE: EVERYTHING ON THE SHELF<") }] : [];
    const t = await render(undefined, 5353, B, files);
    const rs = specImplementation(B, t.measured);
    expect(rs.filter((r) => r.by === "tokens" && r.status === "implemented").map((r) => r.id)).toEqual([]);
    expect(rs.find((r) => r.id === "signature")?.status).toBe("for the coder");
    expect(rs.find((r) => r.id === "heading-case")?.status).toBe("for the coder");
    expect(t.journeyFailed).toEqual([]);
  }, 180_000);
});
